<map version="1.0.1">
<node TEXT="共控机测试用例思维导图"><node TEXT="火灾报警业务（报不报 · 5.4.1）"><node TEXT="单点报警（默认路径，无需任何确认）"><node TEXT="探测器加烟报警 ⇒ ≤10 s 声光、总灯常亮、部位+时间记录（年月日时分秒）、保持至复位【P0·FA-01】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.1.2 原文】当有火灾探测器的火灾报警信号输入时，控制器应在 10 s 内发出火灾报警声、光信号。火灾报警信号准许设置报警延时，其最大延时不应超过 1 min，延时期间应有延时光指示，延时时间应采用倒计时方式显示，延时设置信息应能通过本机操作查询。</p><p>【6.3.2 原文】使一只火灾探测器发出火灾报警信号，测量从火灾探测器发出火灾报警信号至试样发出火灾报警信号的时间间隔，观察并记录试样发出的火灾报警声、光信号（包括火警总指示、部位或探测区指示等）情况及计时、打印情况。</p></body></html></richcontent></node><node TEXT="按下手报 ⇒ ≤10 s 报警，基线同上，且明确标注&quot;手报&quot;类型【P0·FA-02】"></node><node TEXT="报警期间做查询/自检等各类操作 ⇒ 不影响火警接收与发出（仅屏蔽/复位例外）【P0·FA-13】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.1.13 原文】除屏蔽和复位操作外，对控制器的任何操作均不应影响控制器接收和发出火灾报警信号。</p></body></html></richcontent></node></node><node TEXT="报警延时（可选功能）"><node TEXT="设延时（≤1 min）后触发探测器 ⇒ 报警延时红灯亮 + LCD 倒计时，不进火警状态；走完→火警包整体解锁【可选·FA-04】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.1.2 原文】当有火灾探测器的火灾报警信号输入时，控制器应在 10 s 内发出火灾报警声、光信号。火灾报警信号准许设置报警延时，其最大延时不应超过 1 min，延时期间应有延时光指示，延时时间应采用倒计时方式显示，延时设置信息应能通过本机操作查询。</p></body></html></richcontent></node><node TEXT="延时期间按手报 ⇒ 立即报警（手报无延时许可，没许可=禁止）【P0·FA-03】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.1.2 原文】当有火灾探测器的火灾报警信号输入时，控制器应在 10 s 内发出火灾报警声、光信号。火灾报警信号准许设置报警延时，其最大延时不应超过 1 min，延时期间应有延时光指示，延时时间应采用倒计时方式显示，延时设置信息应能通过本机操作查询。</p></body></html></richcontent></node><node TEXT="延时期间复位 ⇒ 延时作废回正常监视【FA-10 路径】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.1.10 原文】控制器应设手动复位按钮(键)，操作手动复位按钮(键)，控制器应在 20 s 内完成复位，并在显示器上显示完成复位的状态信息；仍然存在的报警状态及相关信息应保持或在 20 s 内重新建立。</p></body></html></richcontent></node></node><node TEXT="多信号确认（可选功能）"><node TEXT="同点/同区二次确认：信号① ⇒ 仅提示声+部位，总灯不亮/无输出/不上报/不占首火警；60 s 内信号②（同一只复位后再报 或 同区另一只）⇒ 整包解锁；30 min 无后续 ⇒ 自动复位【可选·FA-08】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.1.8 原文】控制器需要接收来自同一探测器(区)两个或两个以上火灾报警信号才能确定发出火灾报警信号时，满足下述要求：a) 控制器接收到第一个火灾报警信号时，应发出火灾报警声信号或故障报警声信号，并指示相应的报警部位，但不能进入火灾报警状态；b) 接收到第一个火灾报警信号后，控制器在 60 s 内接收到要求的后续火灾报警信号时，应发出火灾报警声、光信号，并进入火灾报警状态；c) 接收到第一个火灾报警信号后，控制器在 30 min 内仍未接收到要求的后续火灾报警信号时，应对第一个火灾报警信号自动复位。</p></body></html></richcontent></node><node TEXT="跨部位确认：第一只 ⇒ 不进火警；第二只（不同部位）⇒ 进火警；≥5 min 无后续 ⇒ 准许自动复位【可选·FA-09】"></node></node><node TEXT="多火警显示"><node TEXT="逐个加报警直到屏放不下（源数=屏容量+1 起步，用回路模拟工装）⇒ 首火警钉顶不参与循环；后续按时间序循环；显示总数；查询一次一条；事件记录完整【P0·FA-07】"></node></node><node TEXT="消音"><node TEXT="火警中消音 → 另一部位再报警 ⇒ 声重新启动、消音灯熄灭【P0·FA-06】"></node></node><node TEXT="复位"><node TEXT="撤除全部报警源后复位 ⇒ ≤20 s 完成+显示复位完成；20 s 观察无报警回来【P0·FA-10①】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.1.10 原文】控制器应设手动复位按钮(键)，操作手动复位按钮(键)，控制器应在 20 s 内完成复位，并在显示器上显示完成复位的状态信息；仍然存在的报警状态及相关信息应保持或在 20 s 内重新建立。</p></body></html></richcontent></node><node TEXT="保留一路（还在烟里）复位 ⇒ 两段计时各 ≤20 s（或仍存报警全程保持不消失，第二段免计时）【P0·FA-10②】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.1.10 原文】控制器应设手动复位按钮(键)，操作手动复位按钮(键)，控制器应在 20 s 内完成复位，并在显示器上显示完成复位的状态信息；仍然存在的报警状态及相关信息应保持或在 20 s 内重新建立。</p></body></html></richcontent></node></node><node TEXT="计时与记录"><node TEXT="连续 24 h 比对时钟（摸底可用频率法：69 ppm 内预判）⇒ 日误差 ≤6 s；主档=电子记录+黑匣子，打印机仅副本【P1·FA-11】"></node></node><node TEXT="特殊接入（可选功能）"><node TEXT="独立供电探测器（线型/吸气/图像型，须有数据通道）：真实触发 ⇒ 透传显示探测器自产的部位/时间信息【可选·FA-05】"></node><node TEXT="远程阈值设定：Ⅲ 级改灵敏度档→退出设置→普通菜单查 ⇒ 值正确且设置界面外可查、断电保持【可选·FA-12】"></node></node></node><node TEXT="联动控制业务（动不动 · 5.4.2）"><node TEXT="自动模式下"><node TEXT="火警满足联动逻辑 ⇒ ≤3 s 启动相关控制输出（起点=触发器件信号到达）【P0·LC-02①】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.2.6 原文】控制器在接收火灾报警信号后 3 s 内应启动相关的控制输出（有延时要求时除外）。</p></body></html></richcontent></node><node TEXT="火警状态成立 ⇒ 警报器控制输出出现（有源测 24 V / 无源测干接点闭合）【P0·LC-01】"></node><node TEXT="受控设备动作给反馈 ⇒ ≤10 s 反馈声光，保持至设备恢复【P0·LC-08】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.2.9 原文】控制器发出消防联动设备控制信号时，应发出相应的声光信号指示，该光信号指示不能被覆盖且应保持至手动恢复；在接收到消防联动设备反馈信号 10 s 内应发出相应的声光信号，并保持至消防联动设备恢复。</p></body></html></richcontent></node><node TEXT="启动后 10 s 未收到反馈 ⇒ 启动光信号转闪亮（值班员警觉态）【P0·LC-08/LC-06】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.2.9 原文】控制器发出消防联动设备控制信号时，应发出相应的声光信号指示，该光信号指示不能被覆盖且应保持至手动恢复；在接收到消防联动设备反馈信号 10 s 内应发出相应的声光信号，并保持至消防联动设备恢复。</p></body></html></richcontent></node><node TEXT="配了输出延时的通道（可选）：延时期间不输出、延时灯亮；≤10 min 步长 ≤1 min；手动插入/手报直启立即放行；不影响其他输出【可选路径·LC-09/LC-02②】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.2.10 原文】如需要设置控制输出延时，延时按下述方式设置：a) 对火灾声和/或光警报器及对消防联动设备控制输出的延时，应通过火灾探测器和/或手动火灾报警按钮和/或特定部位触发的信号实现；b) 控制火灾报警信息传输的延时应通过火灾探测器和/或特定部位触发的信号实现；c) 延时不应超过 10 min，延时时间变化步长不应超过 1 min；d) 在延时期间，应能手动插入或通过手动火灾报警按钮直接启动输出功能；e) 任一输出延时均不应影响其他输出功能的正常工作，延时期间应有延时光指示。</p><p>【5.4.2.6 原文】控制器在接收火灾报警信号后 3 s 内应启动相关的控制输出（有延时要求时除外）。</p></body></html></richcontent></node><node TEXT="多信号输出确认（可选）：第一信号 ⇒ 必须进火警状态（整包成立）唯独输出不动；信号到齐 ⇒ 输出【可选·LC-10】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.2.11 原文】当控制器要求接收来自火灾探测器和/或手动火灾报警按钮的 1 个以上火灾报警信号才能发出控制输出时，当收到第一个火灾报警信号后，在收到要求的后续火灾报警信号前，控制器应进入火灾报警状态；但准许设有分别或全部禁止对火灾声和/或光警报器、火灾报警传输设备和消防联动设备输出操作的手段。禁止对某一设备输出操作不应影响对其他设备的输出操作。</p></body></html></richcontent></node></node><node TEXT="手动模式下"><node TEXT="火警满足联动逻辑 ⇒ 不出自动输出，挂成&quot;请求&quot;（直控启动键闪亮）；报警层/上传/反馈照常【P0·LC-03】"></node><node TEXT="按联动启动按钮 ⇒ 按已接收火警+预设逻辑放行输出（圆形红钮 φ≥12、防误碰、禁密码）【P1·LC-04】"></node><node TEXT="按直控单元启动键（闪亮那个）⇒ 逐路放行：键转常亮、启动/反馈灯闪→收反馈转常亮【P1·LC-06】"></node><node TEXT="按停止键 ⇒ 输出停止；启停键同按不释放 ⇒ 不启动输出【P1·LC-06】"></node></node><node TEXT="模式转换"><node TEXT="自复位钥匙开关切手/自动 ⇒ 状态灯正确；复位不改变控制状态；Ⅱ 级操作【P0·LC-03】"></node><node TEXT="粒度说明：手/自动=整机唯一全局开关；分区粒度走输出禁止/隔离体系（不是多个手自动开关）"></node></node><node TEXT="直控单元硬件"><node TEXT="操作模拟 MCU 失效装置后按启停键 ⇒ 指示灯与控制输出照常工作（硬件直控通道）【P1·LC-07】"></node><node TEXT="受控设备发故障信号 ⇒ 输出故障灯常亮【P1·LC-06】"></node><node TEXT="测输出电压/电流/容量 ⇒ 满足厂商声明【P1·LC-06】"></node><node TEXT="点数判据随产品形态：无联动=2～5 点封顶；带联动=按 GB 16806 ≥6 组【P1·LC-06】"></node></node><node TEXT="对外信息"><node TEXT="火警信息传输（发送/接收双灯，闪=进行中/常亮=完成保持至复位）【可选占位·LC-12 待细化】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.2.8 原文】具有传输火灾报警信息功能的控制器，应具有独立的发送信息和接收信息指示灯。在发送火灾报警信息期间，发送指示灯应闪亮；发送信息结束后，发送指示灯应常亮，并保持至复位。接收反馈信息期间，接收指示灯应闪亮；接收信息结束后，接收指示灯应常亮，并保持至复位。</p></body></html></richcontent></node><node TEXT="火警部位信息下发消防电气控制装置 ⇒ 装置端显示正确【P1·LC-13】"></node><node TEXT="输出禁止/隔离手段：三类输出分别禁、互不影响、状态可见、复位不清【可选·LC-14】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.2.11 原文】当控制器要求接收来自火灾探测器和/或手动火灾报警按钮的 1 个以上火灾报警信号才能发出控制输出时，当收到第一个火灾报警信号后，在收到要求的后续火灾报警信号前，控制器应进入火灾报警状态；但准许设有分别或全部禁止对火灾声和/或光警报器、火灾报警传输设备和消防联动设备输出操作的手段。禁止对某一设备输出操作不应影响对其他设备的输出操作。</p></body></html></richcontent></node></node></node><node TEXT="故障监督业务（5.4.3 + 5.4.12）"><node TEXT="十种故障源（手法见详表 §0.3）"><node TEXT="回路断路/短路/接地 ⇒ ≤100 s 故障声光、报部位；短路例外：产生火警信号则按火警办【P0·FT-01】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.3.2 原文】当控制器与其连接的部件间发生故障时，控制器应在 100 s 内发出与火灾报警信号有明显区别的故障报警声、光信号，显示并记录故障报警时间，故障报警声信号应能手动消除，再有故障报警信号输入时，应能再启动；故障报警光信号应保持至故障排除。</p></body></html></richcontent></node><node TEXT="显示盘/警报器/传输/联动线故障 ⇒ ≤100 s 报部位；c)/e) 类不受火警覆盖【P0·FT-02】"></node><node TEXT="电源类（充电线/备电线/主电欠压/电池/存储单元）⇒ ≤100 s 报类型【P0·FT-03】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.3.4 原文】控制器应能显示下述故障的类型：a) 给备用电源充电的充电器与备用电源间连接线的断路、短路故障；b) 备用电源与其负载间连接线的断路故障；c) 主电源欠压；d) 电池故障；e) 运行数据存储单元不能保存数据。</p></body></html></richcontent></node><node TEXT="总线线间电阻低于规定值 ⇒ 报障【P1·FT-11】"></node></node><node TEXT="消音语义（=对已有事件的确认）"><node TEXT="消音后新故障 ⇒ 再响；同一持续故障巡检反复确认 ⇒ 不响（≥3 轮验证）；排除后复发 ⇒ 再响【P0·FT-04】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.3.2 原文】当控制器与其连接的部件间发生故障时，控制器应在 100 s 内发出与火灾报警信号有明显区别的故障报警声、光信号，显示并记录故障报警时间，故障报警声信号应能手动消除，再有故障报警信号输入时，应能再启动；故障报警光信号应保持至故障排除。</p></body></html></richcontent></node></node><node TEXT="复位"><node TEXT="保留故障源复位 ⇒ ≤20 s 完成；尚存故障 ≤100 s 复显；全部排除 ⇒ 指示清空无幽灵故障【P0·FT-05】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.3.8 原文】控制器的故障报警信号在故障排除后，应自动或手动复位。手动复位后，控制器应在 20 s 内完成复位，并在显示器上显示完成复位的状态信息。复位后，控制器应在 100 s 内重新显示尚存在的故障。</p></body></html></richcontent></node></node><node TEXT="隔离与保持"><node TEXT="总线短路 ⇒ 隔离器动作、指示部位、波及 ≤32 点、段外照常（条件适用：总线制必做）【P0·FT-09】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.3.11 原文】当控制器采用总线工作方式时，应设有总线短路隔离器。短路隔离器动作时，控制器应能指示出被隔离部件的部位号或故障部位号。当某一总线发生一处短路故障导致短路隔离器动作时，受短路隔离器影响的部件数量不应超过 32 个。</p></body></html></richcontent></node><node TEXT="任一故障存在 ⇒ 非故障部分仍达标（七类故障×存活功能矩阵，重新计时）【P0·FT-07】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.3.9 原文】任一故障均不应影响非故障部分的正常工作。</p></body></html></richcontent></node><node TEXT="主电断+备电不足 ⇒ 临终蜂鸣 ≥1 h【P1·FT-06】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.3.6 原文】当主电源断电，备用电源不能保证控制器正常工作时，控制器应发出声故障报警信号并应能保持 1 h 以上。</p></body></html></richcontent></node><node TEXT="故障总灯：火警中/自检中/屏蔽时制造故障 ⇒ 总灯均点亮（不过显示仲裁）【P0·FT-12】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.3.1 原文】控制器应设故障总指示灯(器)，无论控制器处于何种状态，只要有故障报警信号输入，该故障总指示灯(器)均应点亮。</p></body></html></richcontent></node><node TEXT="故障信息超屏 ⇒ 可手动查询【P1·FT-08】"></node><node TEXT="火警时 a/b 类故障准许不显示（接地除外仍须显示）【P1·FT-10】"></node></node><node TEXT="看门狗（程序是最不可信的部件）"><node TEXT="模拟 MCU 失效装置 ⇒ ≤100 s 单独系统故障灯 + 进异常状态（不发火警/不输出/不上传，fail-silent）【P0·WD-01】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.3.7 原文】对于软件控制实现各项功能的控制器，当程序不能正常运行或存储器内容出错时，控制器应有单独的故障指示灯显示系统故障。</p><p>【5.4.12.1 原文】控制器应有程序运行监视功能，当不能运行主要功能程序时，控制器应在 100 s 内发出系统故障报警信号，点亮系统故障指示灯，进入异常状态。注：异常状态是控制器程序出错时，不发出火灾报警信号，不启动控制输出，不向消防控制室图形显示装置发送信息的状态。</p></body></html></richcontent></node><node TEXT="存储器内容出错 ⇒ 同上【P0·WD-02】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.3.7 原文】对于软件控制实现各项功能的控制器，当程序不能正常运行或存储器内容出错时，控制器应有单独的故障指示灯显示系统故障。</p></body></html></richcontent></node><node TEXT="各状态下乱输数据 ⇒ 不引起程序意外执行（原子提交）【P0·WD-03】"></node><node TEXT="探测器报警 ⇒ 确认灯同时常亮，与巡检闪烁明显区别【P1·WD-04】"></node></node></node><node TEXT="旁路状态业务（人为改变系统行为，全部带防呆边界）"><node TEXT="屏蔽（可选功能）"><node TEXT="手动屏蔽一只探测器 ⇒ ≤10 s 屏蔽指示、总灯亮、显示屏蔽时间；每次仅 1 只；火警/故障中的不能屏【SH-01】"></node><node TEXT="区内全屏才显示区被屏、回路全屏才显示回路被屏【SH-02】"></node><node TEXT="复位/断电重启 ⇒ 屏蔽状态保持（非易失存储）【SH-03】"></node><node TEXT="屏蔽下非屏蔽部位报警 ⇒ 正常且屏蔽显示不丢【SH-04】"></node><node TEXT="显示不下可查、可单独解除【SH-05】"></node></node><node TEXT="监管报警（可选功能，监的是&quot;灭火战斗力&quot;）"><node TEXT="输入监管信号（阀被关/水位低）⇒ ≤100 s 红色监管声光【SV-01】"></node><node TEXT="消音再启动；复位后仍存 ⇒ ≤60 s 重建【SV-02】"></node><node TEXT="超屏可查【SV-03】"></node></node><node TEXT="自检"><node TEXT="启动自检 ⇒ 输出接点全程不动作【P0·ST-01】"></node><node TEXT="自检 &gt;1 min 或不能自停 ⇒ 非自检部位报警照常【P0·ST-02】"></node><node TEXT="面板灯/显示/音响全检【P0·ST-03】"></node><node TEXT="部位级自检：单点粒度启动/解除、总灯常亮、可查清单（防遗忘靠可见性不靠超时强退）【P1·ST-04】"></node></node><node TEXT="检查功能"><node TEXT="按检查键（方形红钮、不受级别限制）⇒ 四类总数：设计/正常/故障/屏蔽【P1·CK-01】"></node><node TEXT="设计总数不随动态数变【P1·CK-02】"></node><node TEXT="收火警或 1 min 无操作 ⇒ 自动退出（与屏蔽/自检哲学相反：瞬时查询踢掉最安全）【P1·CK-03】"></node></node></node><node TEXT="人机界面与记录"><node TEXT="信息显示等级"><node TEXT="六级信息同时存在 ⇒ 火警&gt;启动&gt;反馈&gt;监管&gt;故障&gt;屏蔽，分区显示、不轮播、低级可查【P0·DP-01/02/03】"></node><node TEXT="灯与显示器可见性：0.8 m 近看灯（手动/自动/检查开启）、其他 3 m【P1·DP-04】"></node></node><node TEXT="操作级别（四级阶梯）"><node TEXT="Ⅰ 级（任何人）：查询/消音/检查/信息确认可用，其余拒绝【P1·OP-01】"></node><node TEXT="Ⅱ 级（值班员，密码/钥匙）：复位/手动启动/自检/调时/手自动【P1·OP-02】"></node><node TEXT="Ⅲ 级（工程师）：编程/延时/改数据；Ⅲ 钥匙可开 Ⅱ，Ⅱ 开不了 Ⅲ【P1·OP-03】"></node><node TEXT="Ⅳ 级（制造商）：改软硬件/导数据，不能经本机【P1·OP-04】"></node><node TEXT="调试状态：可收火警故障但不启动联动输出、信息带调试标记【P1·OP-05】"></node></node><node TEXT="黑匣子（运行数据存储单元）"><node TEXT="全事件记录带年月日时分秒、防篡改【P1·DR-02】"></node><node TEXT="容量 ≥100×/200×、保存 ≥30 d、断电 ≥14 d、首火警独立不覆盖【P1·DR-03】"></node><node TEXT="USB 2.0 Device 授权导出（0x40 帧/CRC16-0xA001）【P1·DR-04】"></node><node TEXT="金属壳 IP54【P2·DR-01】；反压 120% 1 min【P2·DR-05】"></node></node></node><node TEXT="电源业务"><node TEXT="断主电/恢复 ⇒ 无缝切换不误动作、状态灯正确、过流保护【P0·PW-01】"></node><node TEXT="187/220/242 V 三档 ⇒ 全部正常【P0·PW-02】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.11.4 原文】当交流供电电压变动幅度在额定电压(AC 220 V)的 110% 和 85% 范围内，频率范围在 (50±1) Hz 时，控制器应能正常工作。在 5.4.11.2 的规定条件下，其输出直流电压的电压稳定度和负载稳定度不应大于 5%。</p></body></html></richcontent></node><node TEXT="备电电池：禁含钴锂电（设计红线）【P0·PW-08】"></node><node TEXT="备电显示与分段：任一段 &lt;90% 额定 ⇒ 报障【P1·PW-07】"></node><node TEXT="直流输出稳定度 ≤5%【P1·PW-05】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.11.4 原文】当交流供电电压变动幅度在额定电压(AC 220 V)的 110% 和 85% 范围内，频率范围在 (50±1) Hz 时，控制器应能正常工作。在 5.4.11.2 的规定条件下，其输出直流电压的电压稳定度和负载稳定度不应大于 5%。</p></body></html></richcontent></node><node TEXT="1000 m 线尾 10 只探测器 187 V 下齐报 ⇒ 正常【P1·PW-06】"></node><node TEXT="主电容量：设计容量真实负载+30 点报警 4 h（热稳态，贴热电偶看曲线走平）【P2·PW-03】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.11.2 原文】控制器至少一个回路按设计容量连接真实负载（该回路连接线长度为 1000 m 或生产者规定的长度，但不应小于 1000 m，截面积为 1.0 mm² 的铜质绞线），其他回路连接等效负载，主电源容量应能保证控制器在下述条件下，连续正常工作 4 h：a) 控制器容量不超过 10 个报警部位时，所有报警部位均处于报警状态；b) 控制器容量超过 10 个报警部位时，20% 的报警部位（不少于 10 个报警部位，但不超过 30 个报警部位）处于报警状态。</p></body></html></richcontent></node><node TEXT="备电容量：充 24 h→监视 8 h→13 点报警 30 min【P2·PW-04】"><richcontent TYPE="NOTE"><html><head/><body><p>【5.4.11.3 原文】控制器至少一个回路按设计容量连接真实负载，其他回路连接等效负载，备用电源在放电至终止电压条件下，充电 24 h，其容量应可提供控制器在监视状态下工作 8 h 后，在下述情况下正常工作 30 min：a) 控制器容量不超过 10 个报警部位时，所有报警部位均处于报警状态；b) 控制器容量超过 10 个报警部位时，1/15 的报警部位（不少于 10 个报警部位，但不超过 30 个报警部位）处于报警状态。</p></body></html></richcontent></node></node><node TEXT="通信业务"><node TEXT="CRT 上行"><node TEXT="接口 RS485/CAN/以太网、防脱落、以太网防入侵【P0·CM-01】"></node><node TEXT="五类信息上报（类别/名称/部位/位置/时间/状态，含故障恢复）抓包比对【P0·CM-02】"></node><node TEXT="接收授时校准时钟【P0·CM-03】"></node><node TEXT="协议符合附录 C【P0·CM-04】"></node></node><node TEXT="FECbus 下行（如实现）"><node TEXT="帧格式 0x7E/CRC16-0xA001/8N1【P1·CM-10】"></node><node TEXT="地址：主控=1、装置 2～63、总数 ≤62【P1·CM-11】"></node><node TEXT="1 s 未应答重发 ≤3 次【P1·CM-12】"></node><node TEXT="建链：查版本(44)→查当前事件(41)【P1·CM-13】"></node><node TEXT="异常帧应答码正确【P1·CM-14】"></node><node TEXT="代码表核对 + 装置手/自动状态本机显示【P1·CM-15】"></node><node TEXT="独立线路不与报警/联动总线共用【P0·CM-16】；线路任一点断/短仍通信【P1·CM-17】"></node></node></node><node TEXT="气体灭火控制器（GB 16806 4.3，&quot;可以后悔 30 秒的扳机&quot;）"><node TEXT="自动模式下（联动信号触发）"><node TEXT="联动控制器发启动信号 ⇒ 五阶段依次：①启动声光+记录 ②区内警报器 ③延时（0～30 s 倒计时+保护区显示+封舱：关门窗阀/停空调）④喷洒信号+门外警报器 ⑤压力开关反馈→喷洒声光保持至复位【P0·GE-02/06】"><richcontent TYPE="NOTE"><html><head/><body><p>【4.3.2.2 原文】气体灭火控制器接收启动控制信号后，应能按预置逻辑完成以下功能：a) 发出声、光信号，记录时间，声信号应能手动消除，当再次有启动控制信号输入时，应能再次启动；b) 启动声光警报器；c) 进入延时，延时期间应有延时光指示，显示延时时间和保护区域，关闭保护区域的防火门、窗和防火阀等，停止通风空调系统；d) 延时结束后，发出启动喷洒控制信号，并有光指示，启动保护区域的喷洒光警报器；e) 气体喷洒阶段应发出相应的声、光信号并保持至复位，记录时间。</p></body></html></richcontent></node><node TEXT="每阶段向联动控制器上报（启动/延时/喷洒信号/气体喷洒/阀动作——命令发出与执行分开报）【P0·GE-08】"><richcontent TYPE="NOTE"><html><head/><body><p>【4.3.2.9 原文】气体灭火控制器应能向消防联动控制器发送启动控制信号、延时信号、启动喷洒控制信号、气体喷洒信号、故障信号、选择阀和瓶头阀动作信息。</p></body></html></richcontent></node><node TEXT="区 1 走流程 ⇒ 区 2 状态灯/警报器/负载全程不动【P1·GE-07】"><richcontent TYPE="NOTE"><html><head/><body><p>【4.3.2.7 原文】气体灭火控制器应具有分别启动和停止保护区域声光警报器的功能。</p><p>【4.3.2.8 原文】气体灭火控制器每个保护区域应设独立的工作状态指示灯。</p></body></html></richcontent></node></node><node TEXT="手动干预"><node TEXT="延时期间按手动停止 ⇒ ④⑤ 斩断，已封舱动作维持【P0·GE-03】"></node><node TEXT="停止后再来启动信号 ⇒ 流程从头重新执行（停止≠永久闭锁）【P0·GE-04】"></node><node TEXT="自动态手动插入优先；手/自动状态不受复位影响【P0·GE-04】"></node><node TEXT="现场启动按键触发 ⇒ 与联动信号同流程【P0·GE-02】"><richcontent TYPE="NOTE"><html><head/><body><p>【4.3.2.2 原文】气体灭火控制器接收启动控制信号后，应能按预置逻辑完成以下功能：a) 发出声、光信号，记录时间，声信号应能手动消除，当再次有启动控制信号输入时，应能再次启动；b) 启动声光警报器；c) 进入延时，延时期间应有延时光指示，显示延时时间和保护区域，关闭保护区域的防火门、窗和防火阀等，停止通风空调系统；d) 延时结束后，发出启动喷洒控制信号，并有光指示，启动保护区域的喷洒光警报器；e) 气体喷洒阶段应发出相应的声、光信号并保持至复位，记录时间。</p></body></html></richcontent></node></node><node TEXT="边界与红线"><node TEXT="禁止直连探测器（判定留在上级，设计红线）【P0·GE-01】"></node><node TEXT="声优先级：喷洒声&gt;启动声&gt;故障声（两两同时只响高级）【P1·GE-05】"></node><node TEXT="启动声消音后再来启动信号 ⇒ 再响【P0·GE-02a】"><richcontent TYPE="NOTE"><html><head/><body><p>【4.3.2.2 原文】气体灭火控制器接收启动控制信号后，应能按预置逻辑完成以下功能：a) 发出声、光信号，记录时间，声信号应能手动消除，当再次有启动控制信号输入时，应能再次启动；b) 启动声光警报器；c) 进入延时，延时期间应有延时光指示，显示延时时间和保护区域，关闭保护区域的防火门、窗和防火阀等，停止通风空调系统；d) 延时结束后，发出启动喷洒控制信号，并有光指示，启动保护区域的喷洒光警报器；e) 气体喷洒阶段应发出相应的声、光信号并保持至复位，记录时间。</p></body></html></richcontent></node></node><node TEXT="故障/自检/电源"><node TEXT="五类故障 ≤100 s（a/b 报部位、c/d/e 报类型）；阶段×故障双向互检；复位复显+清空【P0·GE-12/13/14】"></node><node TEXT="自检不动作输出、&gt;1 min 不阻断、面板全检【P0·GE-15/16】"></node><node TEXT="主备切换、备电 8 h+30 min、三档电压【GE-17（P0）/GE-18（P2）/GE-19（P0）】"></node><node TEXT="计时 ≤30 s/日、接点容量、断电数据 14 d【P1·GE-10/11/20】"></node></node></node><node TEXT="型式试验（P2 · 认证实验室阶段）"><node TEXT="电气三件套"><node TEXT="绝缘电阻 ≥100 MΩ（500 V DC 60 s，断电池/开关开位/L N 短接/拆压敏）【TT-01】"></node><node TEXT="泄漏电流 ≤0.5 mA【TT-02】"></node><node TEXT="电气强度 1250 V 60 s 不击穿（气灭不做此项）【TT-03】"></node></node><node TEXT="EMC 七项（说胡话/昏过去两种失效形态）"><node TEXT="辐射 10 V/m、传导 140 dBµV、ESD 8/6 kV、EFT 2 kV、浪涌 2 kV、瞬变 500 次、暂降【TT-04～10】"></node></node><node TEXT="气候机械"><node TEXT="低温 -10 ℃ 16 h（箱内当场测功能）、湿热 4 d（先调温后加湿）、耐久 21 d 断电、振动 5 m/s²、碰撞 0.5 J【TT-11～16】"></node><node TEXT="判据锚点：试验中正常监视，试验后回归火警 10 s + 断线报部位"></node></node></node></node>
</map>